curl -s -X POST https://slack.com/api/users.list -d "token=<TOKEN>" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data['ok']:
    for u in data['members']:
        if 'leo' in u.get('real_name','').lower() or 'park' in u.get('real_name','').lower():
            print(u['id'], u['real_name'])
